  batch_id NUMBER,
  reason VARCHAR2(200)
)

--# create_etl_orders_fact
CREATE TABLE etl_orders_fact (
  order_id NUMBER PRIMARY KEY,
  customer_id NUMBER,
  amount NUMBER(12,2),
  status VARCHAR2(20),
  batch_id NUMBER,
  loaded_at TIMESTAMP
)

