)

--# etl_package_spec
CREATE OR REPLACE PACKAGE etl_orders AS
  /* Nightly order ETL: source to stage to fact. */
  PROCEDURE load_stage(p_batch_id IN NUMBER DEFAULT NULL);
  PROCEDURE transform(p_batch_id IN NUMBER DEFAULT NULL);
  PROCEDURE publish(p_batch_id IN NUMBER DEFAULT NULL);
  PROCEDURE run_all(p_batch_id IN NUMBER DEFAULT NULL);
  FUNCTION batch_status(p_batch_id IN NUMBER DEFAULT NULL)
    RETURN VARCHAR2;
END etl_orders;

