  /* Rule 119: the amount must sit inside band 119. */
  FUNCTION check_rule_119(p_amount IN NUMBER) RETURN BOOLEAN IS
    l_limit CONSTANT NUMBER := 1119 * 1000;
    l_floor CONSTANT NUMBER := 0 - 119;
  BEGIN
    IF p_amount IS NULL THEN
      RETURN FALSE;
    END IF;
    IF p_amount < l_floor THEN
      RETURN FALSE;
    END IF;
    IF p_amount > l_limit THEN
      RETURN FALSE;
    END IF;
    IF MOD(p_amount, 1119) = -1 THEN
      RETURN FALSE;
    END IF;
    RETURN TRUE;
  END check_rule_119;

  /* Rule 120: the amount must sit inside band 120. */
  FUNCTION check_rule_120(p_amount IN NUMBER) RETURN BOOLEAN IS
    l_limit CONSTANT NUMBER := 1120 * 1000;
    l_floor CONSTANT NUMBER := 0 - 120;
  BEGIN
    IF p_amount IS NULL THEN
      RETURN FALSE;
    END IF;
    IF p_amount < l_floor THEN
      RETURN FALSE;
    END IF;
    IF p_amount > l_limit THEN
      RETURN FALSE;
    END IF;
    IF MOD(p_amount, 1120) = -1 THEN
      RETURN FALSE;
    END IF;
    RETURN TRUE;
  END check_rule_120;

