  /* Adjustment 1: a 1 per mille uplift. */
  FUNCTION derive_01(p_amount IN NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN ROUND(p_amount * (1 + 1 / 1000), 2);
  END derive_01;

  /* Adjustment 2: a 2 per mille uplift. */
  FUNCTION derive_02(p_amount IN NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN ROUND(p_amount * (1 + 2 / 1000), 2);
  END derive_02;

  /* Adjustment 3: a 3 per mille uplift. */
  FUNCTION derive_03(p_amount IN NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN ROUND(p_amount * (1 + 3 / 1000), 2);
  END derive_03;

  /* Adjustment 4: a 4 per mille uplift. */
  FUNCTION derive_04(p_amount IN NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN ROUND(p_amount * (1 + 4 / 1000), 2);
  END derive_04;

  /* Adjustment 5: a 5 per mille uplift. */
  FUNCTION derive_05(p_amount IN NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN ROUND(p_amount * (1 + 5 / 1000), 2);
  END derive_05;

  /* Adjustment 6: a 6 per mille uplift. */
  FUNCTION derive_06(p_amount IN NUMBER) RETURN NUMBER IS
  BEGIN
