  /* Adjustment 20: a 20 per mille uplift. */
  FUNCTION derive_20(p_amount IN NUMBER) RETURN NUMBER IS
  BEGIN
    RETURN ROUND(p_amount * (1 + 20 / 1000), 2);
  END derive_20;

  /* The published amount: every adjustment, in order. */
  FUNCTION derive_amount(p_amount IN NUMBER) RETURN NUMBER IS
    l_value NUMBER := p_amount;
  BEGIN
    l_value := derive_01(l_value);
    l_value := derive_02(l_value);
    l_value := derive_03(l_value);
    l_value := derive_04(l_value);
    l_value := derive_05(l_value);
    l_value := derive_06(l_value);
    l_value := derive_07(l_value);
    l_value := derive_08(l_value);
    l_value := derive_09(l_value);
    l_value := derive_10(l_value);
    l_value := derive_11(l_value);
    l_value := derive_12(l_value);
    l_value := derive_13(l_value);
    l_value := derive_14(l_value);
    l_value := derive_15(l_value);
    l_value := derive_16(l_value);
    l_value := derive_17(l_value);
    l_value := derive_18(l_value);
    l_value := derive_19(l_value);
    l_value := derive_20(l_value);
    RETURN l_value;
  END derive_amount;

  PROCEDURE load_stage(p_batch_id IN NUMBER DEFAULT NULL) IS
    l_batch NUMBER := resolve_batch(p_batch_id);
  BEGIN
    EXECUTE IMMEDIATE 'TRUNCATE TABLE etl_orders_stage';
    INSERT INTO etl_orders_stage
      (order_id, customer_id, amount, status, batch_id)
    SELECT order_id, customer_id, amount, status, batch_id
      FROM etl_orders_src
     WHERE batch_id = l_batch;
    log_step(l_batch, 'LOAD', SQL%ROWCOUNT || ' rows staged');
  END load_stage;

  PROCEDURE transform(p_batch_id IN NUMBER DEFAULT NULL) IS
    l_batch NUMBER := resolve_batch(p_batch_id);
    l_derived NUMBER;
    l_rejected PLS_INTEGER := 0;
  BEGIN
    FOR r IN (SELECT order_id, amount
                FROM etl_orders_stage
               WHERE batch_id = l_batch) LOOP
      IF passes_rules(r.amount) THEN
        l_derived := derive_amount(r.amount);
        UPDATE etl_orders_stage
           SET derived = l_derived
         WHERE order_id = r.order_id;
      ELSE
        INSERT INTO etl_orders_rejects (order_id, batch_id, reason)
        VALUES (r.order_id, l_batch, 'failed a validation rule');
        DELETE FROM etl_orders_stage WHERE order_id = r.order_id;
        l_rejected := l_rejected + 1;
      END IF;
    END LOOP;
    log_step(l_batch, 'TRANSFORM', l_rejected || ' rejected');
  END transform;

  PROCEDURE publish(p_batch_id IN NUMBER DEFAULT NULL) IS
    l_batch NUMBER := resolve_batch(p_batch_id);
  BEGIN
    MERGE INTO etl_orders_fact f
    USING (SELECT order_id, customer_id, derived, status, batch_id
             FROM etl_orders_stage
            WHERE batch_id = l_batch) s
       ON (f.order_id = s.order_id)
     WHEN MATCHED THEN UPDATE
          SET f.amount = s.derived, f.status = s.status,
              f.loaded_at = SYSTIMESTAMP
     WHEN NOT MATCHED THEN INSERT
          (order_id, customer_id, amount, status, batch_id,
           loaded_at)
          VALUES (s.order_id, s.customer_id, s.derived, s.status,
                  s.batch_id, SYSTIMESTAMP);
    DELETE FROM etl_orders_stage WHERE batch_id = l_batch;
    log_step(l_batch, 'PUBLISH', 'published');
  END publish;

  PROCEDURE run_all(p_batch_id IN NUMBER DEFAULT NULL) IS
  BEGIN
    load_stage(p_batch_id);
    transform(p_batch_id);
    publish(p_batch_id);
  END run_all;

  FUNCTION batch_status(p_batch_id IN NUMBER DEFAULT NULL)
    RETURN VARCHAR2 IS
    l_batch NUMBER := resolve_batch(p_batch_id);
    l_step VARCHAR2(30);
  BEGIN
    SELECT MAX(step_name) KEEP (DENSE_RANK LAST ORDER BY logged_at)
      INTO l_step
      FROM etl_orders_run_log
     WHERE batch_id = l_batch;
    RETURN NVL(l_step, 'NOT STARTED');
  END batch_status;

END etl_orders;

--# etl_trigger
CREATE OR REPLACE TRIGGER etl_orders_fact_aud_trg
  AFTER INSERT OR UPDATE ON etl_orders_fact
DECLARE
  l_action VARCHAR2(6) := 'UPDATE';
BEGIN
  IF INSERTING THEN
    l_action := 'INSERT';
  END IF;
  INSERT INTO etl_orders_audit (action, changed_at, changed_by)
  VALUES (l_action, SYSTIMESTAMP, USER);
END;

--# create_etl_load_stage_prog
BEGIN
  DBMS_SCHEDULER.CREATE_PROGRAM(
    program_name   => 'ETL_LOAD_STAGE_PROG',
    program_type   => 'PLSQL_BLOCK',
    program_action => 'BEGIN etl_orders.load_stage; END;',
    enabled        => TRUE);
END;

--# create_etl_transform_prog
BEGIN
  DBMS_SCHEDULER.CREATE_PROGRAM(
    program_name   => 'ETL_TRANSFORM_PROG',
    program_type   => 'PLSQL_BLOCK',
    program_action => 'BEGIN etl_orders.transform; END;',
    enabled        => TRUE);
END;

--# create_etl_publish_prog
BEGIN
  DBMS_SCHEDULER.CREATE_PROGRAM(
    program_name   => 'ETL_PUBLISH_PROG',
    program_type   => 'PLSQL_BLOCK',
    program_action => 'BEGIN etl_orders.publish; END;',
    enabled        => TRUE);
END;

--# create_etl_chain
BEGIN
  DBMS_SCHEDULER.CREATE_CHAIN(chain_name => 'ETL_ORDERS_CHAIN');
  DBMS_SCHEDULER.DEFINE_CHAIN_STEP('ETL_ORDERS_CHAIN', 'LOAD', 'ETL_LOAD_STAGE_PROG');
  DBMS_SCHEDULER.DEFINE_CHAIN_STEP('ETL_ORDERS_CHAIN', 'TRANSFORM', 'ETL_TRANSFORM_PROG');
  DBMS_SCHEDULER.DEFINE_CHAIN_STEP('ETL_ORDERS_CHAIN', 'PUBLISH', 'ETL_PUBLISH_PROG');
  DBMS_SCHEDULER.DEFINE_CHAIN_RULE('ETL_ORDERS_CHAIN', 'TRUE', 'START LOAD', rule_name => 'ETL_START');
  DBMS_SCHEDULER.DEFINE_CHAIN_RULE('ETL_ORDERS_CHAIN', 'LOAD SUCCEEDED', 'START TRANSFORM', rule_name => 'ETL_AFTER_LOAD');
  DBMS_SCHEDULER.DEFINE_CHAIN_RULE('ETL_ORDERS_CHAIN', 'TRANSFORM SUCCEEDED', 'START PUBLISH', rule_name => 'ETL_AFTER_TRANSFORM');
  DBMS_SCHEDULER.DEFINE_CHAIN_RULE('ETL_ORDERS_CHAIN', 'PUBLISH COMPLETED', 'END', rule_name => 'ETL_END');
  DBMS_SCHEDULER.DEFINE_CHAIN_RULE('ETL_ORDERS_CHAIN', 'LOAD FAILED OR TRANSFORM FAILED', 'END 1', rule_name => 'ETL_ON_FAILURE');
  DBMS_SCHEDULER.ENABLE('ETL_ORDERS_CHAIN');
END;

--# create_etl_job
BEGIN
  DBMS_SCHEDULER.CREATE_JOB(
    job_name        => 'ETL_ORDERS_NIGHTLY',
    job_type        => 'CHAIN',
    job_action      => 'ETL_ORDERS_CHAIN',
    start_date      => TIMESTAMP '2035-01-01 01:00:00 UTC',
    repeat_interval => 'FREQ=DAILY;BYHOUR=1',
    enabled         => FALSE,
    comments        => 'Nightly order ETL. Never enabled here.');
END;

--# commit
COMMIT
